let celebrationQueue=[],celebrationTimer=null,foilQueue=[],activeFoil=null,foilSequence=0;
function setPackInert(value){$('#drawn').inert=value;$('.opening-actions').inert=value;$('#opening > .close').inert=value;}
function resetCelebration(){clearTimeout(celebrationTimer);celebrationTimer=null;celebrationQueue=[];foilQueue=[];if(activeFoil)clearTimeout(activeFoil.timer);activeFoil=null;foilSequence++;$('#foil-stage').hidden=true;$('#foil-stage').innerHTML='';setPackInert(false);$('#rarity-celebration').hidden=true;$('#rarity-celebration').innerHTML='';}
function celebrateCard(card){if(!['Epic','Legendary'].includes(card.rarity))return;celebrationQueue.push(card);if(!celebrationTimer&&!activeFoil)showNextCelebration();}
function showNextCelebration(){if(activeFoil){celebrationTimer=null;return;}if(!celebrationQueue.length||!$('#opening').open){celebrationTimer=null;$('#rarity-celebration').hidden=true;return;}const card=celebrationQueue.shift(),host=$('#rarity-celebration');host.hidden=false;host.dataset.level=card.rarity;host.innerHTML=`<div class="rarity-orbit"></div><div class="rarity-rays"></div><div class="rarity-sparks" aria-hidden="true">${Array.from({length:18},(_,i)=>`<i style="--spark:${i}"></i>`).join('')}</div><div class="rarity-announcement"><span>${card.rarity==='Legendary'?'✦':'◆'}</span><strong>${escapeText(card.rarity)}</strong><p>${escapeText(card.name)}</p></div>`;celebrationTimer=setTimeout(()=>{host.hidden=true;celebrationTimer=setTimeout(showNextCelebration,150);},window.matchMedia('(prefers-reduced-motion: reduce)').matches?1200:1900);}
function requestFoilReveal(index){if(revealed.has(index)||activeFoil?.index===index||foilQueue.includes(index))return;foilQueue.push(index);if(!activeFoil)startNextFoil();}
function startNextFoil(){if(!foilQueue.length||!$('#opening').open)return;clearTimeout(celebrationTimer);celebrationTimer=null;$('#rarity-celebration').hidden=true;const index=foilQueue.shift(),source=$(`[data-reveal="${index}"]`),rect=source?.getBoundingClientRect?.()||{left:0,top:0,width:0,height:0};activeFoil={index,taps:0,busy:false,complete:false,timer:null,sequence:++foilSequence};setPackInert(true);const host=$('#foil-stage');host.hidden=false;host.dataset.phase='sealed';host.innerHTML=`<div class="foil-stage-aura" aria-hidden="true"></div><div class="foil-stage-heading"><p class="eyebrow">AN ARCHIVE FOIL IS WAITING</p><h2>Break the seal.</h2></div><div class="foil-card-position"><div id="foil-card-host" class="foil-card-host" data-charge="0" style="--fly-x:${rect.left+rect.width/2-(window.innerWidth||1024)/2}px;--fly-y:${rect.top+rect.height/2-(window.innerHeight||768)/2}px"><button id="foil-unseal" class="foil-sealed-card" aria-label="Charge Archive Foil, click 1 of 3"><span class="foil-inner-border"></span><small>THE POLITICAL ARCHIVE</small><span class="foil-seal-mark">PA</span><strong>ARCHIVE<br>FOIL</strong><span class="foil-seal-rule"></span><small>IDENTITY SEALED</small></button></div></div><div class="foil-stage-footer"><p id="foil-instruction" role="status">Click the card 3 more times to reveal it.</p><div class="foil-charge-dots" aria-label="0 of 3 charges"><i></i><i></i><i></i></div><button class="text-link" id="foil-return">Return to packet</button></div>`;$('#foil-unseal').onclick=chargeFoil;$('#foil-return').onclick=finishFoilStage;$('#foil-unseal').focus();}
function chargeFoil(){const f=activeFoil;if(!f||f.busy||f.complete||f.taps>=3)return false;f.taps++;f.busy=true;const host=$('#foil-card-host'),button=$('#foil-unseal');host.dataset.charge=String(f.taps);button.disabled=true;button.dataset.shake=String(f.taps);const dots=$('.foil-charge-dots');dots.setAttribute('aria-label',`${f.taps} of 3 charges`);dots.innerHTML=Array.from({length:3},(_,i)=>`<i class="${i<f.taps?'charged':''}"></i>`).join('');$('#foil-instruction').textContent=f.taps===3?'The seal is breaking…':`${f.taps} of 3 clicks · ${3-f.taps} more to reveal`;const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;f.timer=setTimeout(()=>{if(activeFoil!==f||f.sequence!==foilSequence)return;f.timer=null;if(f.taps===3){f.complete=true;completeReveal(f.index,true);$('#foil-stage').dataset.phase='revealed';host.innerHTML=cardHTML(draws[f.index].card,{isNew:draws[f.index].isNew,revealed:true});$('.foil-stage-heading').innerHTML=`<p class="eyebrow">ARCHIVE FOIL · SEAL BROKEN</p><h2>${escapeText(draws[f.index].card.name)}</h2>`;$('#foil-instruction').textContent='Your Archive Foil is in the collection.';$('#foil-return').textContent=foilQueue.length?'Reveal the next Archive Foil →':'Back to packet →';$('#foil-return').className='primary';$('#foil-return').focus();}else{f.busy=false;button.disabled=false;button.removeAttribute('data-shake');button.setAttribute('aria-label',`Charge Archive Foil, click ${f.taps+1} of 3`);button.focus();}},reduced?180:f.taps===3?950:f.taps===2?650:480);return true;}
function finishFoilStage(){if(!activeFoil)return;const f=activeFoil;clearTimeout(f.timer);if(!f.complete)foilQueue=[];activeFoil=null;$('#foil-stage').hidden=true;$('#foil-stage').innerHTML='';setPackInert(false);if(foilQueue.length){startNextFoil();return;}if(!f.complete)$('#reveal-hint').textContent='An Archive Foil is still sealed. Tap its card to continue.';const target=$(`#drawn [data-opened-index="${f.index}"]`)||$(`[data-reveal="${f.index}"]`)||$('#reveal-all');target?.focus();if(celebrationQueue.length)showNextCelebration();}
$('#opening').addEventListener('close',resetCelebration);
